// Kill-switch Service Worker.
// Reemplaza (override) al sw.min.js de la gem jekyll-theme-chirpy para forzar
// que el navegador detecte una actualizacion, limpie las caches viejas y se
// desregistre. Ver incidente: el SW de Chirpy quedaba "congelado" porque sus
// bytes no cambian entre deploys del sitio (issue cotes2020/jekyll-theme-chirpy#527).

self.addEventListener('install', () => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const cacheNames = await caches.keys();
      await Promise.all(cacheNames.map((name) => caches.delete(name)));

      await self.clients.claim();

      const clients = await self.clients.matchAll({ type: 'window' });
      clients.forEach((client) => client.navigate(client.url));

      await self.registration.unregister();
    })()
  );
});
